import { z } from "zod";

export const OtpOptionsSchema = z
  .object({
    templateName: z
      .string()
      .regex(/^[a-z0-9_]{1,512}$/)
      .describe(
        "Name of an approved AUTHENTICATION template with a copy-code/OTP URL button at index 0",
      ),
    languageCode: z
      .string()
      .regex(/^[a-z]{2,3}(?:_[A-Z]{2})?$/)
      .describe("Exact approved template language, for example pt_BR or en_US"),
    otpCode: z
      .string()
      .regex(/^[A-Za-z0-9]{4,15}$/)
      .describe(
        "One-time code generated by your trusted backend; WAMCP does not generate, validate or invalidate it",
      ),
  })
  .strict();

export const SendOtpSchema = OtpOptionsSchema.extend({
  instanceId: z
    .string()
    .min(1)
    .describe(
      "Cloud API instance to send from; native authentication templates are not available on Baileys",
    ),
  to: z
    .string()
    .regex(/^\+?[1-9][0-9]{6,14}(?:@s\.whatsapp\.net)?$/)
    .describe(
      "Individual recipient phone number or phone JID; groups, LIDs and broadcasts are rejected",
    ),
  requestId: z
    .string()
    .regex(/^[A-Za-z0-9_-]{8,128}$/)
    .describe(
      "Unique backend request ID. Reuse only for the same code/template. A separate Redis reservation deduplicates it for 24 hours",
    ),
  deliveryTtlSeconds: z
    .number()
    .int()
    .min(10)
    .max(600)
    .default(120)
    .describe(
      "Maximum local queue wait before sending; default 120 seconds. Does not set the code's validity or change the approved template expiry footer",
    ),
}).strict();
